pragma solidity ^0.8.26;

error InvalidSwapLimits(uint256 _length);
error InsufficientOutputAmount(uint256 _amountOut, uint256 _minAmountOut);

/// @title SwapLimits
/// @author Agustin Aguilar
/// @notice Optional per-operation limits carried in swap adapter `adapterCalldata`
/// @dev Empty calldata means no limits. Otherwise it is `abi.encode(uint256 minAmountOut)` or, for adapters
/// that support it, `abi.encode(uint256 minAmountOut, uint160 sqrtPriceLimitX96)`. A zero price limit keeps the
/// adapter's default limit. The minimum is checked against the increase of the inbox `tokenOut` balance, not the
/// amount the pool reports, so a token that charges on transfer cannot pass it with less than `minAmountOut`.
/// These limits come from the executor calldata and are not signed; they protect the executor's own swap from third
/// parties, not the inbox from the executor.
library SwapLimits {
  function decodeMinAmountOut(bytes calldata _data) internal pure returns (uint256 _minAmountOut) {
    uint256 length = _data.length;
    if (length == 0) {
      return 0;
    }
    if (length != 32) {
      revert InvalidSwapLimits(length);
    }

    return abi.decode(_data, (uint256));
  }

  function decode(bytes calldata _data) internal pure returns (uint256 _minAmountOut, uint160 _sqrtPriceLimitX96) {
    uint256 length = _data.length;
    if (length == 0) {
      return (0, 0);
    }
    if (length == 32) {
      return (abi.decode(_data, (uint256)), 0);
    }
    if (length != 64) {
      revert InvalidSwapLimits(length);
    }

    return abi.decode(_data, (uint256, uint160));
  }

  function requireMinAmountOut(uint256 _balanceBefore, uint256 _balanceAfter, uint256 _minAmountOut) internal pure {
    uint256 received = _balanceAfter > _balanceBefore ? _balanceAfter - _balanceBefore : 0;
    if (received < _minAmountOut) {
      revert InsufficientOutputAmount(received, _minAmountOut);
    }
  }
}

