// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {LocalAdapter} from "./LocalAdapter.sol";
import {SwapLimits} from "./SwapLimits.sol";
import {InvalidUniswapQuote, UniswapQuote} from "./UniswapQuote.sol";
import {LocalQuote} from "../interfaces/ILocalAdapter.sol";
import {IUniswapV3Factory} from "../interfaces/IUniswapV3Factory.sol";
import {IUniswapV3Pool} from "../interfaces/IUniswapV3Pool.sol";
import {IUniswapV3SwapCallback} from "../interfaces/IUniswapV3SwapCallback.sol";
import {IWETH} from "../interfaces/IWETH.sol";

/// @title UniswapV3Adapter
/// @author Agustin Aguilar
/// @notice Swap adapter for single-pool Uniswap v3 exact-input swaps
contract UniswapV3Adapter is LocalAdapter, IUniswapV3SwapCallback {
  uint160 private constant MIN_SQRT_RATIO = 4_295_128_739;
  uint160 private constant MAX_SQRT_RATIO = 1_461_446_703_485_210_103_287_273_052_203_988_822_378_723_970_342;

  struct SwapCallbackData {
    address route;
    address inbox;
    address tokenIn;
    address tokenOut;
    bool quote;
    uint256 amountIn;
  }

  IUniswapV3Factory public immutable FACTORY;
  IWETH public immutable WETH;
  uint24 public immutable FEE;

  event UniswapV3RouteExecuted(
    address indexed _inbox,
    address indexed _tokenIn,
    address indexed _tokenOut,
    uint24 _fee,
    uint256 _amountIn,
    uint256 _amountOut
  );

  error ZeroAddress();
  error InvalidFee();
  error InvalidAmount();
  error UnsupportedRoute(address _tokenIn, address _tokenOut);
  error PoolNotFound(address _tokenIn, address _tokenOut, uint24 _fee);
  error UnauthorizedPool(address _pool);
  error InvalidSwapDelta(int256 _amount0Delta, int256 _amount1Delta);
  error InvalidConsumedAmount(uint256 _expected, uint256 _actual);

  constructor(address _factory, address _weth, uint24 _fee) {
    if (_factory == address(0) || _weth == address(0)) {
      revert ZeroAddress();
    }
    if (_fee == 0) {
      revert InvalidFee();
    }

    FACTORY = IUniswapV3Factory(_factory);
    WETH = IWETH(_weth);
    FEE = _fee;
  }

  /// @notice Quotes a Uniswap v3 exact-input swap for an explicit non-zero input amount.
  function quote(address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata)
    external
    override
    returns (LocalQuote memory _quote)
  {
    address tokenIn = _routeToken(_tokenIn);
    address tokenOut = _routeToken(_tokenOut);
    if (tokenIn == tokenOut) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }

    address pool = FACTORY.getPool(tokenIn, tokenOut, FEE);
    if (pool == address(0)) {
      revert PoolNotFound(tokenIn, tokenOut, FEE);
    }

    if (_amountIn == 0 || _amountIn > uint256(type(int256).max)) {
      revert InvalidAmount();
    }
    bool zeroForOne = tokenIn < tokenOut;

    try IUniswapV3Pool(pool)
      .swap(
        address(this),
        zeroForOne,
        int256(_amountIn),
        _sqrtPriceLimit(zeroForOne),
        abi.encode(
          SwapCallbackData({
            route: address(0), inbox: address(0), tokenIn: tokenIn, tokenOut: tokenOut, quote: true, amountIn: _amountIn
          })
        )
      ) returns (
      int256, int256
    ) {
      revert InvalidUniswapQuote();
    } catch (bytes memory reason) {
      return UniswapQuote.decode(reason);
    }
  }

  /// @notice Executes a Uniswap v3 exact-input swap. `_amountIn == 0` uses the full inbox balance.
  /// @dev `_adapterCalldata` is empty, `abi.encode(uint256 minAmountOut)` or
  /// `abi.encode(uint256 minAmountOut, uint160 sqrtPriceLimitX96)`. `minAmountOut` is checked against the inbox
  /// balance increase. The price limit is in pool terms (sqrt of token1 per token0, with native mapped to WETH): when
  /// the route token in sorts below the token out (`zeroForOne`) it must be below the current price, otherwise above
  /// it, or the pool reverts. A non-zero price limit makes the swap fill-or-revert: stopping at the limit before
  /// consuming the full input reverts.
  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    bytes calldata _adapterCalldata
  ) external override returns (uint256 _amountOut) {
    address tokenIn = _routeToken(_tokenIn);
    address tokenOut = _routeToken(_tokenOut);
    if (tokenIn == tokenOut) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }

    address pool = FACTORY.getPool(tokenIn, tokenOut, FEE);
    if (pool == address(0)) {
      revert PoolNotFound(tokenIn, tokenOut, FEE);
    }

    (uint256 minAmountOut, uint160 sqrtPriceLimitX96) = SwapLimits.decode(_adapterCalldata);
    uint256 balanceBefore = minAmountOut == 0 ? 0 : _inboxAssetBalance(_inbox, _tokenOut);
    uint256 amountIn = _prepareInput(_inbox, _tokenIn, tokenIn, _amountIn);
    if (amountIn > uint256(type(int256).max)) {
      revert InvalidAmount();
    }
    bool zeroForOne = tokenIn < tokenOut;

    (int256 amount0, int256 amount1) = IUniswapV3Pool(pool)
      .swap(
        _inbox,
        zeroForOne,
        int256(amountIn),
        sqrtPriceLimitX96 == 0 ? _sqrtPriceLimit(zeroForOne) : sqrtPriceLimitX96,
        abi.encode(
          SwapCallbackData({
            route: msg.sender, inbox: _inbox, tokenIn: tokenIn, tokenOut: tokenOut, quote: false, amountIn: amountIn
          })
        )
      );

    if (sqrtPriceLimitX96 != 0) {
      int256 amountConsumed = zeroForOne ? amount0 : amount1;
      if (amountConsumed != int256(amountIn)) {
        revert InvalidConsumedAmount(amountIn, amountConsumed < 0 ? 0 : uint256(amountConsumed));
      }
    }

    _amountOut = _swapOutputAmount(zeroForOne, amount0, amount1);
    if (_tokenOut == address(0)) {
      _executeInboxTransactionFromRoute(msg.sender, _inbox, tokenOut, 0, abi.encodeCall(IWETH.withdraw, (_amountOut)));
    }
    if (minAmountOut != 0) {
      SwapLimits.requireMinAmountOut(balanceBefore, _inboxAssetBalance(_inbox, _tokenOut), minAmountOut);
    }

    emit UniswapV3RouteExecuted(_inbox, _tokenIn, _tokenOut, FEE, amountIn, _amountOut);
  }

  /// @inheritdoc IUniswapV3SwapCallback
  function uniswapV3SwapCallback(int256 _amount0Delta, int256 _amount1Delta, bytes calldata _data) external {
    SwapCallbackData memory data = abi.decode(_data, (SwapCallbackData));
    address pool = FACTORY.getPool(data.tokenIn, data.tokenOut, FEE);
    if (msg.sender != pool) {
      revert UnauthorizedPool(msg.sender);
    }

    bool zeroForOne = data.tokenIn < data.tokenOut;
    int256 amountDelta = zeroForOne ? _amount0Delta : _amount1Delta;
    if (amountDelta <= 0) {
      revert InvalidSwapDelta(_amount0Delta, _amount1Delta);
    }
    uint256 amountOut = _swapOutputAmount(zeroForOne, _amount0Delta, _amount1Delta);

    if (data.quote) {
      UniswapQuote.revertQuote(data.amountIn, amountOut);
    }

    _executeInboxTokenTransferFromRoute(data.route, data.inbox, data.tokenIn, msg.sender, uint256(amountDelta));
  }

  function _prepareInput(address _inbox, address _requestedTokenIn, address _tokenIn, uint256 _requestedAmountIn)
    internal
    returns (uint256 _amountIn)
  {
    if (_requestedTokenIn == address(0)) {
      _amountIn = _resolveAmountIn(_requestedAmountIn, _inbox.balance);
      if (_amountIn == 0) {
        revert InvalidAmount();
      }

      _executeInboxTransaction(_inbox, _tokenIn, _amountIn, abi.encodeCall(IWETH.deposit, ()));
    } else {
      _amountIn = _resolveAmountIn(_requestedAmountIn, IERC20(_tokenIn).balanceOf(_inbox));
      if (_amountIn == 0) {
        revert InvalidAmount();
      }
    }
  }

  function _swapOutputAmount(bool _zeroForOne, int256 _amount0, int256 _amount1) internal pure returns (uint256) {
    int256 amountOut = _zeroForOne ? -_amount1 : -_amount0;
    if (amountOut <= 0) {
      revert InvalidAmount();
    }

    return uint256(amountOut);
  }

  function _sqrtPriceLimit(bool _zeroForOne) internal pure returns (uint160) {
    return _zeroForOne ? MIN_SQRT_RATIO + 1 : MAX_SQRT_RATIO - 1;
  }

  function _routeToken(address _token) internal view returns (address) {
    return _token == address(0) ? address(WETH) : _token;
  }
}

